import json

log_path = "/home/ubuntu/.agent-ml-research-idea_gen_0509_11/projects/turn_residual_gating/logs/workers/worker_eval_attention_steering_eval200_20260520T093707.log"
with open(log_path) as f:
    lines = f.readlines()

# Check lines 52, 56, 62, 70 for their SSH commands and data
for line_num in [51, 55, 61, 69]:  # 0-indexed
    entry = json.loads(lines[line_num])
    msg = entry.get("message", {})
    content = msg.get("content", [])
    for item in content:
        if isinstance(item, dict):
            if "name" in item and "ssh" in str(item.get("name", "")):
                print(f"Line {line_num+1}: SSH command: {item['input'].get('command', 'N/A')[:100]}")
            elif "content" in item:
                c = str(item["content"])
                if "ppl_per_conversation" in c:
                    print(f"Line {line_num+1}: Tool result, len={len(c)}, truncated={'截断' in c}")
                    # Try to extract the stdout
                    try:
                        inner = json.loads(item["content"])
                        result = json.loads(inner["result"])
                        stdout = result["data"]["stdout"]
                        print(f"  stdout len={len(stdout)}, truncated={'截断' in stdout}")
                        if "截断" not in stdout:
                            # Try parsing
                            data = json.loads(stdout)
                            print(f"  Valid JSON! Keys: {list(data.keys())}")
                            if "results" in data:
                                print(f"  Result betas: {list(data['results'].keys())}")
                    except Exception as e:
                        print(f"  Parse error: {e}")

    # Also check the next line
    if line_num + 1 < len(lines):
        next_entry = json.loads(lines[line_num + 1])
        next_content = next_entry.get("message", {}).get("content", [])
        for item in next_content:
            if isinstance(item, dict) and "content" in item:
                c = str(item["content"])
                if "ppl_per_conversation" in c:
                    print(f"Line {line_num+2}: Tool result, len={len(c)}, truncated={'截断' in c}")

PYEOF
